/**
 * Definition for a rope tree node. class RopeTreeNode { int len; String val; RopeTreeNode left;
 * RopeTreeNode right; RopeTreeNode() {} RopeTreeNode(String val) { this.len = 0; this.val = val; }
 * RopeTreeNode(int len) { this.len = len; this.val = ""; } RopeTreeNode(int len, TreeNode left,
 * TreeNode right) { this.len = len; this.val = ""; this.left = left; this.right = right; } }
 */
class Solution {
  public char getKthCharacter(RopeTreeNode root, int k) {

    // dfs; so use stack

    StringBuilder sb = new StringBuilder();

    Deque<RopeTreeNode> stack = new LinkedList<>();

    stack.push(root);

    while (!stack.isEmpty()) {

      RopeTreeNode curNode = stack.pop();

      if (curNode.val.equals("")) { // internal node
        if (curNode.right != null) {
          stack.push(curNode.right);
        }
        if (curNode.left != null) {
          stack.push(curNode.left);
        }
      } else { // leaf node
        sb.append(curNode.val);
      }
    }

    return sb.charAt(k - 1);
  }
}
